import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousFileChannel;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.concurrent.Future;

public class AsyncIoDemonstration {
    public static void readFileAsync(Path path) throws Exception {
        AsynchronousFileChannel fileChannel = AsynchronousFileChannel.open(path, StandardOpenOption.READ);
        ByteBuffer buffer = ByteBuffer.allocate(1024);

        // Non-blocking call: returns a Future immediately while OS reads file in background
        Future<Integer> operation = fileChannel.read(buffer, 0);

        System.out.println("Request dispatched. Doing other work on thread: " + Thread.currentThread().getName());

        // Wait for the result only when needed
        while (!operation.isDone()) {
            Thread.sleep(10);
        }

        System.out.println("Bytes read asynchronously: " + operation.get());
        fileChannel.close();
    }
}
